parameters.jsCode:
// Limpieza de HTML a texto legible
const html = $input.item.json.data;

// Eliminar scripts, styles, y tags
let text = html
  .replace(/<script[^>]*>.*?<\/script>/gis, '')
  .replace(/<style[^>]*>.*?<\/style>/gis, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .trim();

// Limitar a 8000 caracteres para no saturar la API
if (text.length > 8000) {
  text = text.substring(0, 8000) + '...';
}

// Extraer metadatos adicionales del HTML
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const descriptionMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
const h1Match = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);

return {
  cleanText: text,
  originalUrl: $('Webhook').item.json.body.url,
  userEmail: $('Webhook').item.json.body.email,
  source: $('Webhook').item.json.body.source || 'widget_flotante',
  metadata: {
    title: titleMatch ? titleMatch[1] : 'No encontrado',
    description: descriptionMatch ? descriptionMatch[1] : 'No encontrada',
    h1: h1Match ? h1Match[1] : 'No encontrado'
  }
};

